function up(p,sharp=22,rad=50){const ax=Math.abs(p.x),ay=Math.abs(p.y),az=Math.abs(p.z);const c=Math.max(ax,ay,az),k=sharp/rad;
 const wx=Math.exp(k*(ax-c)),wy=Math.exp(k*(ay-c)),wz=Math.exp(k*(az-c)),s=wx+wy+wz;
 return new THREE.Vector3((wx/s)*Math.sign(p.x||1),(wy/s)*Math.sign(p.y||1),(wz/s)*Math.sign(p.z||1)).normalize();}
function tang(u){return [new THREE.Vector3(1,0,0),new THREE.Vector3(0,1,0),new THREE.Vector3(0,0,1)].filter(a=>Math.abs(a.dot(u))<0.5);}
function plan(f,g,u){return planAgentSurfaceRoute(terrain,PLANET,f,g,{face:surfaceFaceFromUp(u),differentFaceFallback:'unreachable',allowJetpackCrossing:false,maxJetpackWaterCells:3,maxJetpackWaterDepthCells:2,jetpackDetourExtraCells:4,jetpackDetourRatio:1.5,maxVisitedCells:4096});}
