  const diff=goal.clone().sub(term); diff.addScaledVector(u,-diff.dot(u));
  const comps=tang(u).map(a=>diff.dot(a));
  const max=Math.max(...comps.map(Math.abs));
  console.log(`feetS=${s.toFixed(2)} feetX=${feet.x.toFixed(3)} centreX=${centre.x.toFixed(3)} ux=${u.x.toFixed(4)} term=${term.toArray().map(n=>n.toFixed(2))} tang=[${comps.map(n=>n.toFixed(4))}] max=${max.toFixed(4)} ${max>REACH?'NEEDS-COLUMN':''} ${max>1?'OUTSIDE-CELL':''} distToGoal=${(o-s).toFixed(3)}`);
}
