  type CommonGroundSnapshot
} from './commonGroundState.ts';
import {
  CG_FIXED_SOCKET,
  checkReference,
  evaluateOfferedSpan,
  WORKER_BODY_HEIGHT,
  bodiesClear,
  nextOccupancy,
  playerSocket,
  routeProgressUnits,
  walkedSegmentSupported,
