        actor.seedCommonGroundActorPose({ x: -34, y: 51.05, z: 10 });
        frame.setPlayerWorldPosition(new THREE.Vector3(-34, 51.05, 10));
        for (let f = 0; f < 20; f += 1) director.tickCommonGround(0.016);
