function standAt(point: { x: number; y: number; z: number }): void {
  const up = getPlayerUp();
  setPlayerWorldPosition(new THREE.Vector3(
    point.x + up.x * CG_PLAYER_GROUND_OFFSET,
    point.y + up.y * CG_PLAYER_GROUND_OFFSET,
