  setPlayerWorldPosition(new THREE.Vector3(point.x, point.y, point.z));
}

function distanceFrom(
  a: { x: number; y: number; z: number },
  b: { x: number; y: number; z: number }
): number {
  return Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
}

