});

// --- PC-SAVE-OVERWRITTEN: an autosave must not destroy the world it left ------------
//
// Reproduces the loss the producer harvested from the actual run-4 capture:
// an earned, unfinished ch13 survey (phase drawing, 4 samples, 2.0905 walked,
// 1186 bytes) came back as `phase: "idle"`, 606 bytes, `working: null`.
//
// The ordering is the point, and the storage snapshot alone could not identify
// it: the write is NOT attributed to the Continue click here. Each stage of the
// real boot is stepped through separately so the exact frame that destroys the
// bytes is named.
describe('a partial ch13 survey survives the real Continue lifecycle', () => {
  const ORIGIN = { worldId: STORY_PRIMARY_WORLD_ID, seed: STORY_SEED };
  const SIBLING = { worldId: `${STORY_PRIMARY_WORLD_ID}:p1`, seed: 1600321158 };

  function standOnWorld(worldId: string): void {
    resetSystemFlightForInterstellarArrival({
      system: STORY_COORDINATE,
      activePlanetId: worldId,
      locationMode: 'surface',
      pose: { position: [0, 0, 0], velocity: [0, 0, 0], quaternion: [0, 0, 0, 1] }
    });
    unbind?.();
    unbind = registerCommonGroundWorld({ worldId, footing: flatGround, extraSolids: [] });
  }

  function savedSurvey(worldId: string): Record<string, unknown> | null {
    const raw = (globalThis as unknown as { localStorage: MemStorage })
      .localStorage.getItem(`pvx.v1.world.${worldId}`);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { commonGround?: { survey?: Record<string, unknown> } };
    return parsed.commonGround?.survey ?? null;
  }

  /** Earn a genuine partial drawing on Origin. No fixture, no grant. */
  function earnPartialDrawing(): number {
    standOnWorld(STORY_PRIMARY_WORLD_ID);
    enterBeatThroughTheRealSeam('ch13-survey');
    seedCommonGroundActorPose(CG_POSES.W);
    standAt(CG_POSES.W);
    for (let frame = 0; frame < 20; frame += 1) tickCommonGround(0.016);
    expect(commitCommonGroundDemonstrationOffer()).toBe(true);
    standAt(CG_POSES.S);
    expect(commitCommonGroundSurveyStart()).toBe(true);
    for (const point of CG_ROUTE_SHORT.slice(1, 4)) {
      standAt(point);
      tickCommonGround(0.016);
    }
    tickCommonGround(0.016);
    const samples = commonGroundSnapshot().survey.working?.samples.length ?? 0;
    expect(commonGroundSnapshot().survey.phase).toBe('drawing');
    expect(samples).toBeGreaterThan(1);
    return samples;
  }

  it('names the exact frame that used to destroy the earned bytes', () => {
    installMemStorage();
    const drawn = earnPartialDrawing();
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toMatchObject({ phase: 'drawing' });
    const earned = savedSurvey(STORY_PRIMARY_WORLD_ID)!;
    expect((earned.working as { samples: unknown[] }).samples).toHaveLength(drawn);

    // --- Continue: a cold runtime boots. Nothing has been restored yet. ------
    resetCommonGroundRuntime({ clearWorlds: true });
    resetSignedSceneAvRuntime('sandbox');
    resetCommonGroundActor();
    standOnWorld(STORY_PRIMARY_WORLD_ID);

    // THE FRAME. `restoreCommonGroundForWorld` is a world-keyed React effect and
    // has NOT run yet; something reads the chapter snapshot for the world the
    // app is still nominally on, and that read mints an empty initial snapshot for
    // Origin. No beat has been entered here, so the chapter does not own this
    // world — which is precisely what makes the value an uninitialized snapshot rather than
    // a fact. This is a read, not the Continue click, and not the world switch.
    const initialSnapshot = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(initialSnapshot.hydrated).toBe(false);
    expect(initialSnapshot.survey.phase).toBe('idle');
    expect(isPristineCommonGround(initialSnapshot)).toBe(true);

    // Story entry meanwhile resolves to the sibling world and ch13-return —
    // exactly the beat and coordinate the capture recorded after Continue — so
    // App's world-change autosave writes the world it is LEAVING.
    standOnWorld(SIBLING.worldId);
    // The sibling is the ACTIVE world now, so its own restore effect runs and
    // legitimately finds nothing. Origin's never did.
    restoreCommonGroundForWorld(SIBLING);
    enterBeatThroughTheRealSeam('ch13-return');
    tickCommonGround(0.016);
    saveWorld(ORIGIN);

    // The earned bytes are still there. Previously this wrote phase "idle" with
    // `working: null` over four real samples.
    const afterAutosave = savedSurvey(STORY_PRIMARY_WORLD_ID);
    expect(afterAutosave).toMatchObject({ phase: 'drawing' });
    expect((afterAutosave!.working as { samples: unknown[] }).samples).toHaveLength(drawn);
    expect(afterAutosave!.working).toMatchObject({ walkedUnits: expect.any(Number) });
    expect((afterAutosave!.working as { walkedUnits: number }).walkedUnits).toBeGreaterThan(0);

    // The sibling world DID enter the chapter, so it writes its own — genuinely
    // empty — record, exactly as the capture shows for `-1,-1:p1`. What it must
    // never do is inherit Origin's drawing: no cross-world leak in either
    // direction.
    commonGroundSnapshot(SIBLING.worldId); // the sibling's own live read
    saveWorld(SIBLING);
    expect(savedSurvey(SIBLING.worldId)).toMatchObject({ phase: 'idle', working: null });
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toMatchObject({ phase: 'drawing' });
  });

  it('the initial snapshot does not shadow the payload staged behind it', () => {
    installMemStorage();
    const drawn = earnPartialDrawing();
    saveWorld(ORIGIN);
    resetCommonGroundRuntime({ clearWorlds: true });
    resetSignedSceneAvRuntime('sandbox');
    resetCommonGroundActor();
    standOnWorld(STORY_PRIMARY_WORLD_ID);

    // Initial snapshot first...
    expect(commonGroundSnapshot(STORY_PRIMARY_WORLD_ID).hydrated).toBe(false);

    // ...and only THEN the restore effect fires, exactly as CommonGroundWorld
    // orders it (a world-keyed useEffect, which runs after the first render).
    // The earned state must still win over the uninitialized snapshot minted ahead of it.
    restoreCommonGroundForWorld(ORIGIN);
    enterBeatThroughTheRealSeam('ch13-survey');
    tickCommonGround(0.016);
    const resumed = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(resumed.hydrated).toBe(true);
    expect(resumed.survey.phase).toBe('drawing');
    expect(resumed.survey.working?.samples).toHaveLength(drawn);
    expect(resumed.survey.working?.samples[0]).toMatchObject({
      x: CG_POSES.S.x, z: CG_POSES.S.z
    });

    // Silent restore: nothing already earned is replayed into fresh AV history.
    expect(activatedAnchors()).not.toContain('anc.cg.survey-started');
    expect(activatedAnchors()).not.toContain('anc.cg.demonstration-opened');

    // And a NEW real act is live and activates its own AV.
    for (const point of CG_ROUTE_SHORT.slice(4)) {
      standAt(point);
      tickCommonGround(0.016);
    }
    standAt(CG_POSES.E);
    expect(commitCommonGroundSpanOffer()).toBe(true);
    tickCommonGround(0.016);
    expect(commonGroundSnapshot().survey.phase).toBe('offered');
    expect(activatedAnchors()).toContain('anc.cg.route-offered');
  });

  it('a lawful continuous save with its earned predecessor resumes the survey', () => {
    // The run-4 fixture seeded ch13-fault-reviewed and ch13-return-chosen but
    // never `story:ch13-origin-landed`, and `storyEntryPoint` resolves exactly
    // that set to ch13-return. Resuming at the boarding beat was therefore
    // LAWFUL for those milestones — a fixture predecessor gap, not a wrong-world
    // selection bug. With the earned predecessor present, the same bytes resume
    // in the survey.
    installMemStorage();
    markMilestone(STORY_MILESTONES.ch13FaultReviewed);
    markMilestone(STORY_MILESTONES.ch13ReturnChosen);
    expect(storyEntryPoint()).toMatchObject({ chapter: 'ch13', beat: 'ch13-return' });
    markMilestone(STORY_MILESTONES.ch13OriginLanded);
    expect(storyEntryPoint()).toMatchObject({ chapter: 'ch13', beat: 'ch13-survey' });

    const drawn = earnPartialDrawing();
    saveWorld(ORIGIN);
    resetCommonGroundRuntime({ clearWorlds: true });
    resetSignedSceneAvRuntime('sandbox');
    resetCommonGroundActor();
    standOnWorld(STORY_PRIMARY_WORLD_ID);
    restoreCommonGroundForWorld(ORIGIN);
    enterBeatThroughTheRealSeam(
      storyEntryPoint().beat as 'ch13-survey'
    );
    tickCommonGround(0.016);

    const resumed = commonGroundSnapshot();
    expect(resumed.hydrated).toBe(true);
    expect(resumed.survey.phase).toBe('drawing');
    expect(resumed.survey.working?.samples).toHaveLength(drawn);
    // Still no manufactured completion receipt.
    expect(hasMilestone(STORY_MILESTONES.ch13RouteTested)).toBe(false);
    // The pose the save recorded is where he stands, not a replayed journey.
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toMatchObject({ phase: 'drawing' });
  });

  it('retains, but never grafts, another actor\'s payload on disk', () => {
    installMemStorage();
    earnPartialDrawing();
    saveWorld(ORIGIN);
    // Rewrite the ACTUAL stored record so the foreign owner is what the real
    // restore route finds; nothing is staged by hand here.
    const store = (globalThis as unknown as { localStorage: MemStorage }).localStorage;
    const key = `pvx.v1.world.${STORY_PRIMARY_WORLD_ID}`;
    const record = JSON.parse(store.getItem(key)!) as { commonGround: { actorId: string } };
    record.commonGround.actorId = 'someone-else';
    store.setItem(key, JSON.stringify(record));
    const foreign = savedSurvey(STORY_PRIMARY_WORLD_ID);
    expect(foreign).toMatchObject({ phase: 'drawing' });

    resetCommonGroundRuntime({ clearWorlds: true });
    resetCommonGroundActor();
    standOnWorld(STORY_PRIMARY_WORLD_ID);
    restoreCommonGroundForWorld(ORIGIN);

    // The validator rejects it and local state initializes instead...
    const local = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(local.hydrated).toBe(false);
    expect(local.survey.phase).toBe('idle');
    expect(local.actorId).not.toBe('someone-else');

    // ...and rejecting a payload is a hydration decision, never a licence for
    // this actor's empty state to erase the other actor's bytes.
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toEqual(foreign);
    // Still true after further ordinary autosaves.
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toEqual(foreign);
  });

  /** The whole stored chapter field, not just its survey. */
  function savedChapter(worldId: string): unknown {
    const raw = (globalThis as unknown as { localStorage: MemStorage })
      .localStorage.getItem(`pvx.v1.world.${worldId}`);
    if (!raw) return undefined;
    return (JSON.parse(raw) as { commonGround?: unknown }).commonGround;
  }

  it('an EARLIER empty restore never licenses erasing a payload read later', () => {
    // Ownership has a lifetime. This world answered "nothing here" once, which
    // lawfully lets emptiness be saved. Later, IN THE SAME SESSION, a present
    // payload is actually read for it. That newer read cannot borrow the older
    // absent answer: if the validator rejects the payload, the empty local
    // state must NOT be allowed to write itself over bytes that are really there.
    installMemStorage();
    const drawn = earnPartialDrawing();
    saveWorld(ORIGIN);
    const store = (globalThis as unknown as { localStorage: MemStorage }).localStorage;
    const key = `pvx.v1.world.${STORY_PRIMARY_WORLD_ID}`;
    const record = JSON.parse(store.getItem(key)!) as { commonGround: { actorId: string } };
    record.commonGround.actorId = 'someone-else';
    const arrivesLater = JSON.stringify(record);
    store.removeItem(key);

    // --- a session that first reads this world while it is genuinely empty ---
    resetCommonGroundRuntime({ clearWorlds: true });
    resetSignedSceneAvRuntime('sandbox');
    resetCommonGroundActor();
    standOnWorld(STORY_PRIMARY_WORLD_ID);
    restoreCommonGroundForWorld(ORIGIN); // absent: a real answer
    enterBeatThroughTheRealSeam('ch13-survey');
    tickCommonGround(0.016);
    // Emptiness is a fact after that read, and it may lawfully be saved.
    expect(isPristineCommonGround(commonGroundSnapshot(STORY_PRIMARY_WORLD_ID))).toBe(false);
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toMatchObject({ phase: 'idle' });

    // --- the same world now really does hold a payload, and it is READ -------
    store.setItem(key, arrivesLater);
    const foreign = savedSurvey(STORY_PRIMARY_WORLD_ID);
    expect(foreign).toMatchObject({ phase: 'drawing' });
    expect((foreign!.working as { samples: unknown[] }).samples).toHaveLength(drawn);
    restoreCommonGroundForWorld(ORIGIN);

    // The validator rejects it and local state initializes, exactly as before...
    const local = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(local.hydrated).toBe(false);
    expect(local.survey.phase).toBe('idle');
    expect(local.actorId).not.toBe('someone-else');
    // ...but the stale absent answer does not survive the newer present read.
    expect(isPristineCommonGround(local)).toBe(true);
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toEqual(foreign);
    // Still true after further ordinary autosaves in the same session.
    saveWorld(ORIGIN);
    tickCommonGround(0.016);
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toEqual(foreign);
  });

  it('keeps a MALFORMED payload read after an empty one, and still plays on', () => {
    installMemStorage();
    earnPartialDrawing();
    saveWorld(ORIGIN);
    const store = (globalThis as unknown as { localStorage: MemStorage }).localStorage;
    const key = `pvx.v1.world.${STORY_PRIMARY_WORLD_ID}`;
    const record = JSON.parse(store.getItem(key)!) as { commonGround: unknown };
    record.commonGround = { survey: 'not-a-record', common: 7 };
    const damaged = JSON.stringify(record);
    store.removeItem(key);

    resetCommonGroundRuntime({ clearWorlds: true });
    resetSignedSceneAvRuntime('sandbox');
    resetCommonGroundActor();
    standOnWorld(STORY_PRIMARY_WORLD_ID);
    restoreCommonGroundForWorld(ORIGIN); // absent
    enterBeatThroughTheRealSeam('ch13-survey');
    tickCommonGround(0.016);
    saveWorld(ORIGIN);

    store.setItem(key, damaged);
    const onDisk = savedChapter(STORY_PRIMARY_WORLD_ID);
    restoreCommonGroundForWorld(ORIGIN);
    const local = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(local.hydrated).toBe(false);
    saveWorld(ORIGIN);
    // Unreadable is not empty: the damaged bytes are kept for a repair, not
    // silently replaced by this actor's idle state.
    expect(savedChapter(STORY_PRIMARY_WORLD_ID)).toEqual(onDisk);

    // And the chapter is not frozen by that: real new play still saves.
    seedCommonGroundActorPose(CG_POSES.W);
    standAt(CG_POSES.W);
    for (let f = 0; f < 20; f += 1) tickCommonGround(0.016);
    expect(commitCommonGroundDemonstrationOffer()).toBe(true);
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID))
      .toMatchObject({ phase: commonGroundSnapshot(STORY_PRIMARY_WORLD_ID).survey.phase });
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).not.toBe('not-a-record');
    expect(savedChapter(STORY_PRIMARY_WORLD_ID)).not.toEqual(onDisk);
  });

  it('survives an autosave in the window between staging and hydration', () => {
    // A completed READ of a present payload is not proof it was validated. If
    // an autosave lands after the restore stages the bytes but before the next
    // tick consumes them, the uninitialized snapshot must still not answer for the world.
    installMemStorage();
    const drawn = earnPartialDrawing();
    saveWorld(ORIGIN);

    resetCommonGroundRuntime({ clearWorlds: true });
    resetSignedSceneAvRuntime('sandbox');
    resetCommonGroundActor();
    standOnWorld(STORY_PRIMARY_WORLD_ID);

    // Initial snapshot exists first, restore then stages the earned payload...
    enterBeatThroughTheRealSeam('ch13-survey');
    expect(commonGroundSnapshot(STORY_PRIMARY_WORLD_ID).hydrated).toBe(false);
    restoreCommonGroundForWorld(ORIGIN);

    // ...and the autosave lands HERE, before any tick consumes it.
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toMatchObject({ phase: 'drawing' });

    // The very next tick then hydrates it, and it is still all there.
    tickCommonGround(0.016);
    const resumed = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(resumed.hydrated).toBe(true);
    expect(resumed.survey.working?.samples).toHaveLength(drawn);
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toMatchObject({ phase: 'drawing' });
  });

  it('never lets a late payload overwrite genuinely newer live work', () => {
    installMemStorage();
    earnPartialDrawing();
    saveWorld(ORIGIN);
    const stale = JSON.parse(
      (globalThis as unknown as { localStorage: MemStorage })
        .localStorage.getItem(`pvx.v1.world.${STORY_PRIMARY_WORLD_ID}`)!
    ) as { commonGround: unknown };

    // Live work continues past the save, then the old bytes arrive late.
    for (const point of CG_ROUTE_SHORT.slice(4)) {
      standAt(point);
      tickCommonGround(0.016);
    }
    const live = commonGroundSnapshot().survey.working?.samples.length ?? 0;
    stageCommonGroundWorldPayload(STORY_PRIMARY_WORLD_ID, stale.commonGround);
    const after = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(after.survey.working?.samples).toHaveLength(live);
    expect(after.hydrated).toBe(false); // still the live run, not a restore
  });

  it('an explicit world clear still removes the record', () => {
    // Retention must not become immortality: the deliberate reset path is
    // unchanged, and it takes the whole record with it.
    installMemStorage();
    earnPartialDrawing();
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).not.toBeNull();
    clearWorldStateForWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toBeNull();
    saveWorld(ORIGIN);
    expect(savedSurvey(STORY_PRIMARY_WORLD_ID)).toBeNull();
  });
});

// --- Regression guards for the ownership signal itself --------------------------------
describe('beat entry is not proof that a world was restored', () => {
  const ORIGIN = { worldId: STORY_PRIMARY_WORLD_ID, seed: STORY_SEED };

  function savedSurveyPhase(): string | undefined {
    const raw = (globalThis as unknown as { localStorage: MemStorage })
      .localStorage.getItem(`pvx.v1.world.${STORY_PRIMARY_WORLD_ID}`);
    if (!raw) return undefined;
    return (JSON.parse(raw) as {
      commonGround?: { survey?: { phase?: string } };
    }).commonGround?.survey?.phase;
  }

  function standOrigin(): void {
    resetSystemFlightForInterstellarArrival({
      system: STORY_COORDINATE,
      activePlanetId: STORY_PRIMARY_WORLD_ID,
      locationMode: 'surface',
      pose: { position: [0, 0, 0], velocity: [0, 0, 0], quaternion: [0, 0, 0, 1] }
    });
    unbind?.();
    unbind = registerCommonGroundWorld({
      worldId: STORY_PRIMARY_WORLD_ID, footing: flatGround, extraSolids: []
    });
  }

  function earn(): number {
    standOrigin();
    restoreCommonGroundForWorld(ORIGIN);
    enterBeatThroughTheRealSeam('ch13-survey');
    seedCommonGroundActorPose(CG_POSES.W);
    standAt(CG_POSES.W);
    for (let f = 0; f < 20; f += 1) tickCommonGround(0.016);
    expect(commitCommonGroundDemonstrationOffer()).toBe(true);
    standAt(CG_POSES.S);
    expect(commitCommonGroundSurveyStart()).toBe(true);
    for (const point of CG_ROUTE_SHORT.slice(1, 4)) {
      standAt(point);
      tickCommonGround(0.016);
    }
    tickCommonGround(0.016);
    return commonGroundSnapshot().survey.working?.samples.length ?? 0;
  }

  it('entering the booting beat BEFORE the restore still keeps the earned bytes', () => {
    // The exact ordering root flagged: the director enters ch13-survey on the
    // booting world first, and only afterwards does the world-keyed restore
    // effect stage the saved payload. If beat entry counted as ownership, the
    // uninitialized snapshot would be authoritative and would overwrite the save again.
    installMemStorage();
    const drawn = earn();
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).toBe('drawing');

    resetCommonGroundRuntime({ clearWorlds: true });
    resetSignedSceneAvRuntime('sandbox');
    resetCommonGroundActor();
    standOrigin();

    // Beat entry FIRST, restore later.
    enterBeatThroughTheRealSeam('ch13-survey');
    tickCommonGround(0.016);
    expect(commonGroundSnapshot(STORY_PRIMARY_WORLD_ID).hydrated).toBe(false);
    expect(isPristineCommonGround(commonGroundSnapshot(STORY_PRIMARY_WORLD_ID))).toBe(true);

    // An autosave landing in this window must not destroy the drawing.
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).toBe('drawing');

    // And when the restore finally runs, the earned state takes over.
    restoreCommonGroundForWorld(ORIGIN);
    tickCommonGround(0.016);
    const resumed = commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    expect(resumed.hydrated).toBe(true);
    expect(resumed.survey.working?.samples).toHaveLength(drawn);
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).toBe('drawing');
  });

  it('a completed restore that finds nothing DOES make emptiness a fact', () => {
    // The other side of the same signal: a legacy or brand-new record with no
    // chapter field is a real answer, and the world may then write itself.
    installMemStorage();
    standOrigin();
    restoreCommonGroundForWorld(ORIGIN);
    enterBeatThroughTheRealSeam('ch13-survey');
    tickCommonGround(0.016);
    expect(isPristineCommonGround(commonGroundSnapshot(STORY_PRIMARY_WORLD_ID))).toBe(false);
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).toBe('idle');
  });

  it('a legitimately new action after a bare entry is never dropped', () => {
    installMemStorage();
    standOrigin();
    // No restore has run; the snapshot starts as an initial snapshot...
    enterBeatThroughTheRealSeam('ch13-survey');
    expect(isPristineCommonGround(commonGroundSnapshot())).toBe(true);
    // ...but real play immediately makes it authoritative, initial snapshot or not.
    seedCommonGroundActorPose(CG_POSES.W);
    standAt(CG_POSES.W);
    for (let f = 0; f < 20; f += 1) tickCommonGround(0.016);
    expect(commitCommonGroundDemonstrationOffer()).toBe(true);
    expect(isPristineCommonGround(commonGroundSnapshot())).toBe(false);
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).not.toBe(undefined);
  });

  it('the explicit scoped clear removes the stored chapter field for good', () => {
    installMemStorage();
    earn();
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).toBe('drawing');

    clearCommonGroundForWorld(ORIGIN);
    expect(savedSurveyPhase()).toBeUndefined();
    // Carry-forward must not resurrect it on the next save, or on a reload.
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).toBeUndefined();
    restoreCommonGroundForWorld(ORIGIN);
    enterBeatThroughTheRealSeam('ch13-survey');
    expect(commonGroundSnapshot().survey.phase).toBe('idle');
    expect(commonGroundSnapshot().hydrated).toBe(false);
    saveWorld(ORIGIN);
    expect(savedSurveyPhase()).toBe('idle');
  });
});

// --- CG-IMPL-012: standing clear is a physical place ---------------------------------
//
// MEASURED on hardware: the movie drew and offered the long survey (42 samples,
// 35.308 units), the rail then requested the standby at (-42, 51.05, 9), and her
// body never left ground [-41.965326, 50.988996, 12.155896] — routeAction
// 'direct', stillTime 0, nudges 0 — while W-7744 held for body clearance.
//
// This block runs the REAL footing (`createFooting` over the real generator at
// the audit site's own identity: seed 3215739679, world '-1,-1', planetSize 50,
// VOXEL_SCALE 2) and the REAL surface planner with `nextNavigationStep`'s own
// option set, because a fixture plot answers 'supported' everywhere and cannot
// see water. Every earlier standby assertion in this chapter would have passed
// on the broken target.

describe('the standby she is sent to is ground she can actually stand on', () => {
  const PLANET_SIZE = 50;
  const UP = new THREE.Vector3(0, 1, 0);
  /** The shipped standby before this repair, kept as the reproduction subject. */
  const PRE_REPAIR_STANDBY = { x: CG_POSES.E.x, y: CG_POSES.E.y, z: CG_POSES.E.z - 3 };
  /** The candidate the causal audit proposed, and the producer rejected. */
  const REJECTED_LONG_ROUTE_CANDIDATES = [
    { x: -42, y: 51.05, z: 20 },
    { x: -42, y: 51.05, z: 22 }
  ];
  /** The exact pose the hardware stalled at. */
  const STALL_BODY = { x: -41.965326, y: 50.988996, z: 12.155896 };
  /** `commonGroundActor` body clearance + the rail's pose stop radius, both ways. */
  const REQUIRED_CLEARANCE = 1 * 2 + 0.6;

  function realFooting(): CommonGroundFooting {
    return createFooting(PLANET_SIZE, STORY_SEED, STORY_PRIMARY_WORLD_ID);
  }

  function realTerrain() {
    return createLiveAgentSurfaceTerrain(PLANET_SIZE, STORY_SEED, STORY_PRIMARY_WORLD_ID);
  }

  /** `nextNavigationStep` -> `planReachableCrossFaceRoute`, option for option. */
  function planLikeRuntime(
    from: { x: number; y: number; z: number },
    to: { x: number; y: number; z: number }
  ) {
    return planAgentSurfaceRoute(
      realTerrain(),
      PLANET_SIZE,
      new THREE.Vector3(from.x, from.y, from.z),
      new THREE.Vector3(to.x, to.y, to.z),
      {
        face: surfaceFaceFromUp(UP),
        differentFaceFallback: 'unreachable',
        allowJetpackCrossing: false,
        maxJetpackWaterCells: 3,
        maxJetpackWaterDepthCells: 2,
        jetpackDetourExtraCells: 4,
        jetpackDetourRatio: 1.5,
        maxVisitedCells: 4096
      }
    );
  }

  function segmentClearance(
    point: { x: number; z: number },
    from: { x: number; z: number },
    to: { x: number; z: number }
  ): number {
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    const lengthSq = dx * dx + dz * dz;
    const px = point.x - from.x;
    const pz = point.z - from.z;
    const t = lengthSq === 0 ? 0 : Math.max(0, Math.min(1, (px * dx + pz * dz) / lengthSq));
    return Math.hypot(px - t * dx, pz - t * dz);
  }

  /** Clearance from the SEGMENTS of a span, never from its vertices alone. */
  function spanClearance(
    point: { x: number; z: number },
    span: readonly { x: number; z: number }[]
  ): number {
    if (span.length === 1) return Math.hypot(point.x - span[0]!.x, point.z - span[0]!.z);
    let nearest = Infinity;
    for (let index = 0; index < span.length - 1; index += 1) {
      nearest = Math.min(nearest, segmentClearance(point, span[index]!, span[index + 1]!));
    }
    return nearest;
  }

  function railTarget(): { x: number; y: number; z: number } | null {
    const plan = commonGroundRailPlan();
    if (!plan.target) return null;
    return { x: plan.target[0], y: plan.target[1], z: plan.target[2] };
  }

  /** Offer a walked route by writing the slot the player would have drawn. */
  function offerRoute(route: readonly { x: number; y: number; z: number }[]): void {
    tickCommonGround(0.016);
    const snapshot = commonGroundSnapshot();
    const slot = createTraceSlot({ ...route[0]!, corner: true });
    for (const point of route.slice(1)) {
      accumulateTraceDistance(slot, 2);
      appendTraceSample(slot, { ...point, corner: false });
    }
    slot.offeredEndIndex = slot.samples.length - 1;
    snapshot.survey.working = slot;
    snapshot.survey.phase = 'offered';
  }

  beforeEach(() => {
    // No placed or persisted blocks: the terrain under the audit site is exactly
    // what the generator produces, which is what the hardware ran.
    voxelSystem.reset();
    unbind?.();
    unbind = registerCommonGroundWorld({ worldId: '', footing: realFooting(), extraSolids: [] });
    enterCommonGroundBeat('ch13-survey');
  });

  afterEach(() => {
    voxelSystem.reset();
  });

  it('REPRODUCES the stall: the pre-repair standby is over water, not ground', () => {
    const footing = realFooting();
    // Not a rounding complaint about an odd coordinate. The lattice-aligned cell
    // centre one unit away is under the same water.
    expect(footing.isSupported(PRE_REPAIR_STANDBY)).toBe(false);
    expect(footing.isSupported({ x: -42, y: 51.05, z: 10 })).toBe(false);
    // ...while the survey line itself, two units north, is real ground.
    expect(footing.isSupported({ x: -42, y: 51.05, z: 12 })).toBe(true);

    // And this is why the body never moved: the planner refused the wet goal and
    // substituted the cell she was already standing in, so the walk was already
    // over before it began.
    const stalled = planLikeRuntime(STALL_BODY, PRE_REPAIR_STANDBY);
    expect(stalled.requestedGoalWasWet).toBe(true);
    expect(stalled.reason).toBe('already-at-resolved-goal');
    expect(stalled.waypoints.length).toBe(1);
    expect(stalled.resolvedGoal?.z).toBeCloseTo(12, 6);
  });

  it('sends her to a supported, REACHABLE standby and never to the old one', () => {
    offerRoute(CG_ROUTE_LONG);
    // She is standing on the span he is about to test.
    standAt({ x: -42, y: 51.05, z: 14 });
    tickCommonGround(0.016);

    const plan = commonGroundRailPlan();
    expect(plan.action).toBe('walk');
    // A place to wait, not a new interaction, objective or reference.
    expect(plan.interactionId).toBeNull();
    const target = railTarget()!;
    expect(target).not.toMatchObject({ x: PRE_REPAIR_STANDBY.x, z: PRE_REPAIR_STANDBY.z });

    // Real ground, by the same footing the chapter's own predicates use.
    expect(realFooting().isSupported(target)).toBe(true);

    // ACTUALLY REACHABLE. Not 'arrived' by cell substitution: the shipped
    // planner returns a dry walking route whose resolved goal IS the target.
    const route = planLikeRuntime(commonGroundPlayerPose(), target);
    expect(route.mode).toBe('walk');
    expect(route.reason).toBe('dry-surface-path');
    expect(route.waypoints.length).toBeGreaterThan(1);
    expect(route.requestedGoalWasWet).toBe(false);
    expect(Math.hypot(route.resolvedGoal!.x - target.x, route.resolvedGoal!.z - target.z))
      .toBeLessThan(1e-6);
  });

  it('clears the whole offered span by SEGMENTS, not by its vertices', () => {
    offerRoute(CG_ROUTE_LONG);
    standAt({ x: -42, y: 51.05, z: 14 });
    tickCommonGround(0.016);
    const target = railTarget()!;

    for (const span of [CG_ROUTE_LONG, CG_ROUTE_SHORT, CG_ROUTE_COMMON, [CG_POSES.E, CG_POSES.H]]) {
      expect(spanClearance(target, span)).toBeGreaterThanOrEqual(REQUIRED_CLEARANCE);
    }
    // ...and clear of his own body and his inspection pose.
    expect(spanClearance(target, [commonGroundActorPosition()]))
      .toBeGreaterThanOrEqual(REQUIRED_CLEARANCE);
    expect(spanClearance(target, [CG_POSES.W])).toBeGreaterThanOrEqual(REQUIRED_CLEARANCE);
  });

  it('REJECTS a candidate that sits on the long survey, however far from COMMON', () => {
    // The proposed repair this replaces. Both points are supported ground and
    // both are metres clear of the common route — and both are ON the span he is
    // about to walk, which is the only thing standing clear means here.
    for (const candidate of REJECTED_LONG_ROUTE_CANDIDATES) {
      expect(realFooting().isSupported(candidate)).toBe(true);
      expect(spanClearance(candidate, CG_ROUTE_COMMON)).toBeGreaterThan(2);
      expect(spanClearance(candidate, CG_ROUTE_LONG)).toBe(0);
    }

    offerRoute(CG_ROUTE_LONG);
    standAt({ x: -42, y: 51.05, z: 14 });
    tickCommonGround(0.016);
    const target = railTarget()!;
    for (const candidate of REJECTED_LONG_ROUTE_CANDIDATES) {
      expect(Math.hypot(target.x - candidate.x, target.z - candidate.z)).toBeGreaterThan(0.5);
    }
  });

  it('answers the ACTUAL recorded span, not an authored route', () => {
    // A recorded excursion that runs straight over the standby the long route
    // would have allowed. The selection has to move; nothing about the authored
    // routes changes.
    const recorded = [
      { x: -26, y: 51.05, z: 12 }, { x: -30, y: 51.05, z: 10 }, { x: -34, y: 51.05, z: 8 },
      { x: -38, y: 51.05, z: 8 }, { x: -40, y: 51.05, z: 8 }, { x: -40, y: 51.05, z: 10 },
      { x: -42, y: 51.05, z: 12 }
    ];
    offerRoute(recorded);
    standAt({ x: -40, y: 51.05, z: 8 });
    tickCommonGround(0.016);

    const plan = commonGroundRailPlan();
    expect(plan.action).toBe('walk');
    const target = railTarget()!;
    expect(spanClearance(target, recorded)).toBeGreaterThanOrEqual(REQUIRED_CLEARANCE);
    expect(realFooting().isSupported(target)).toBe(true);
    const route = planLikeRuntime(commonGroundPlayerPose(), target);
    expect(route.mode).toBe('walk');
    expect(route.reason).toBe('dry-surface-path');
  });

  it('stands clear of his positioning leg and of the common span he will test', () => {
    enterCommonGroundBeat('ch13-common');
    standAt(CG_POSES.E);
    tickCommonGround(0.016);

    const plan = commonGroundRailPlan();
    expect(plan.action).toBe('walk');
    expect(plan.reason).toContain('standing clear');
    const target = railTarget()!;
    expect(realFooting().isSupported(target)).toBe(true);
    // His uncredited positioning leg, and the common route — which is also his
    // independent test, and the span she walks herself afterwards.
    expect(spanClearance(target, [CG_POSES.E, CG_POSES.H]))
      .toBeGreaterThanOrEqual(REQUIRED_CLEARANCE);
    expect(spanClearance(target, CG_ROUTE_COMMON)).toBeGreaterThanOrEqual(REQUIRED_CLEARANCE);
    const route = planLikeRuntime(commonGroundPlayerPose(), target);
    expect(route.mode).toBe('walk');
    expect(route.reason).toBe('dry-surface-path');
  });

  it('HOLDS honestly when nothing qualifies, instead of inventing a place', () => {
    // Ground that carries nobody: no candidate can be published, and a rail that
    // cannot make progress must say so rather than publish a walk to nowhere.
    unbind?.();
    unbind = registerCommonGroundWorld({
      worldId: '',
      footing: { revision: 'no-ground', isSupported: () => false },
      extraSolids: []
    });
    enterCommonGroundBeat('ch13-common');
    standAt(CG_POSES.E);
    tickCommonGround(0.016);

    const plan = commonGroundRailPlan();
    expect(plan.action).toBe('hold');
    expect(plan.target).toBeNull();
    expect(plan.reason).toContain('no target');
  });

  it('keeps his body-clearance hold, and clears it when she has actually moved', () => {
    offerRoute(CG_ROUTE_LONG);
    // She stands ON his span, one sample in front of his approach.
    standAt({ x: -26, y: 51.05, z: 14 });
    for (let frame = 0; frame < 200; frame += 1) tickCommonGround(0.05);

    const snapshot = commonGroundSnapshot();
    expect(snapshot.survey.hold.reason).toBe('body-clearance');
    expect(getCommonGroundActorState().held).toBe(true);
    // And this is the rail that answers it.
    expect(commonGroundRailPlan().reason).toContain('standing clear');

    // She walks to the standby the rail asked for. His hold releases because her
    // body is genuinely out of his way, not because any threshold moved.
    const target = railTarget()!;
    standAt(target);
    for (let frame = 0; frame < 200; frame += 1) tickCommonGround(0.05);
    expect(getCommonGroundActorState().held).toBe(false);
    expect(commonGroundSnapshot().survey.hold.reason).not.toBe('body-clearance');
  });

  it('does not move any signed pose or route while doing it', () => {
    expect(CG_POSES.E).toEqual({ x: -42, y: 51.05, z: 12 });
    expect(CG_POSES.H).toEqual({ x: -40, y: 51.05, z: 12 });
    expect(CG_POSES.W).toEqual({ x: -34, y: 51.05, z: 10 });
    expect(CG_ROUTE_LONG.length).toBe(19);
    expect(CG_ROUTE_COMMON.length).toBe(10);
    expect(CG_COMMON_ROUTE_UNITS).toBe(18);
  });
});

// --- CG-IMPL-010: the published COMMON goals, on the real Origin terrain --------------
//
// MEASURED on hardware twice (journey-common-1/2): the movie earns the route
// test, enters COMMON, places W-7744 at H, then freezes at rail cursor 3 with
// terraUnits 5.845 of 18, body bit-identical, every control false and zero
// nudges. The read-only causal audit reproduced the cause on the shipped planner
// and the shipped terrain, and predicted the same failure at vertices 6 and 9.
//
// WHAT IS REAL HERE, AND WHAT IS NOT.
//
// Real: the goal each case walks toward is the one `commonGroundRailPlan` REALLY
// published for that cursor (no transcription of `railGoal` — the audit's own
// stated limit was that it transcribed the seam it was diagnosing); the shipped
// Origin generator; the shipped A* (`planAgentSurfaceRoute`) with
// `nextNavigationStep`'s option set; the shipped column certification through
// that same planner; the shipped terminal-goal decision
// (`terminalExactGoalHandoff`) and waypoint application
// (`applyTerminalExactGoal`); the shipped steering intent and dead zone; the
// shipped arrival measure (`surfaceGaitDistance`); and the shipped TILTED cube
// up (`smoothUpForPosition`, which is what `EfficientPlayer` publishes — the
// capture's up (-0.019849, 0.999803, ~0) is this function, not a flat +Y).
//
// Not real: no browser runtime, so the body is advanced by the integrator below.
// It moves ONLY along the direction the shipped steering asked for, only while a
// control is held, at a fixed step — it can never arrive at, or teleport onto, a
// point the steering did not walk it to. A walker that simply arrives cannot
// catch this class of bug at all.
//
// THIS IS SOURCE-LEVEL PROOF ON CPU. It is not a hardware, rendering or gameplay
// acceptance claim, and it does not close the manual traversal.

describe('every COMMON rail goal is reachable on the terrain the hardware ran', () => {
  const PLANET_SIZE = 50;
  /** Grounded pose -> capsule centre, the frame `getPlayerWorldPosition` uses. */
  const CENTRE_OFFSET = CG_PLAYER_GROUND_OFFSET;
  /** `exactGoalFootprintColumns`: half a cell, less the capsule radius. */
  const FOOTPRINT_REACH = VOXEL_SCALE / 2 - PLAYER_CAPSULE_RADIUS;
  /**
   * `CG_RAIL_ROUTE_ARRIVE`, the cursor's UNCHANGED tolerance for standing beside
   * a vertex. Written here rather than exported: a test that could move it is a
   * test that could relax it, and this repair does not touch it.
   */
  const VERTEX_REACH = 0.35;

  /** `routeTurnsAt`: the polyline actually changes direction at this vertex. */
  function turnsAt(
    route: readonly { x: number; y: number; z: number }[],
    index: number
  ): boolean {
    const previous = route[index - 1];
    const vertex = route[index];
    const next = route[index + 1];
    if (!previous || !vertex || !next) return false;
    const into = new THREE.Vector3(
      vertex.x - previous.x, vertex.y - previous.y, vertex.z - previous.z
    ).normalize();
    const out = new THREE.Vector3(
      next.x - vertex.x, next.y - vertex.y, next.z - vertex.z
    ).normalize();
    return into.dot(out) < 0.999;
  }

  function realTerrain() {
    return createLiveAgentSurfaceTerrain(PLANET_SIZE, STORY_SEED, STORY_PRIMARY_WORLD_ID);
  }

  /** The shipped surface frame: `EfficientPlayer`'s own smooth-gravity up. */
  function liveUp(centre: THREE.Vector3): THREE.Vector3 {
    return smoothUpForPosition(centre, { radius: PLANET_SIZE });
  }

  /** A grounded pose expressed as the capsule centre the navigator reads. */
  function centreOver(pose: { x: number; y: number; z: number }): THREE.Vector3 {
    const foot = new THREE.Vector3(pose.x, pose.y, pose.z);
    return foot.clone().addScaledVector(liveUp(foot), CENTRE_OFFSET);
  }

  /** `nextNavigationStep`'s planner call, option for option. */
  function planLikeRuntime(
    terrain: ReturnType<typeof realTerrain>,
    from: THREE.Vector3,
    to: THREE.Vector3,
    up: THREE.Vector3
  ) {
    return planAgentSurfaceRoute(terrain, PLANET_SIZE, from, to, {
      face: surfaceFaceFromUp(up),
      differentFaceFallback: 'unreachable',
      allowJetpackCrossing: false,
      maxJetpackWaterCells: 3,
      maxJetpackWaterDepthCells: 2,
      jetpackDetourExtraCells: 4,
      jetpackDetourRatio: 1.5,
      maxVisitedCells: 4096
    });
  }

  /** `nextNavigationStep`'s own column ownership probe, option for option. */
  function certifierFor(terrain: ReturnType<typeof realTerrain>, up: THREE.Vector3) {
    return (column: THREE.Vector3): THREE.Vector3 | null => {
      const probe = planAgentSurfaceRoute(terrain, PLANET_SIZE, column, column, {
        face: surfaceFaceFromUp(up),
        differentFaceFallback: 'unreachable',
        allowJetpackCrossing: false,
        maxVisitedCells: 1
      });
      if (probe.mode === 'unreachable' || probe.requestedGoalWasWet) return null;
      return probe.resolvedGoal;
    };
  }

  /** `nextNavigationStep`'s cursor consumption, tangent-plane measured. */
  function advanceCursor(
    waypoints: readonly THREE.Vector3[],
    cursor: number,
    body: THREE.Vector3,
    up: THREE.Vector3
  ): number {
    let next = cursor;
    const scratch = new THREE.Vector3();
    while (next < waypoints.length - 1) {
      const candidate = waypoints[next];
      if (!candidate) break;
      scratch.copy(candidate).sub(body);
      const vertical = scratch.dot(up);
      scratch.addScaledVector(up, -vertical);
      if (scratch.lengthSq() > 1.35 * 1.35) break;
      if (vertical > 1.0) break;
      if (vertical < -3.4) break;
      next += 1;
    }
    return next;
  }

  /** `steerFreeToward`: the shipped dead zone, then the shipped steering intent. */
  function steer(body: THREE.Vector3, waypoint: THREE.Vector3, up: THREE.Vector3) {
    const delta = new THREE.Vector3().copy(waypoint).sub(body);
    delta.addScaledVector(up, -delta.dot(up));
    if (delta.lengthSq() < NAVIGATION_STEER_DEAD_ZONE * NAVIGATION_STEER_DEAD_ZONE) {
      return { pushing: false, move: new THREE.Vector3() };
    }
    const forward = delta.clone().normalize();
    const intent = surfaceSteeringIntent(delta, up, forward);
    const right = new THREE.Vector3().crossVectors(forward, up).normalize();
    const move = new THREE.Vector3();
    if (intent.forward) move.add(forward);
    if (intent.backward) move.sub(forward);
    if (intent.right) move.sub(right);
    if (intent.left) move.add(right);
    const pushing = intent.forward || intent.backward || intent.left || intent.right;
    if (pushing && move.lengthSq() > 0) move.normalize();
    return { pushing, move };
  }

  interface LegOutcome {
    /** Furthest the FEET ever got past the incoming vertex plane. */
    readonly along: number;
    /** Closest the FEET ever got to the vertex itself. */
    readonly closest: number;
    /** Worst tangential footprint offset the seam measured before crossing. */
    readonly worstFootprintOffset: number;
    /** Refusal strings the real handoff produced before crossing, if any. */
    readonly refusals: readonly string[];
    readonly displacement: number;
    readonly pushedFrames: number;
    readonly frozenFrames: number;
    readonly terminalWaypoint: THREE.Vector3;
  }

  /**
   * Walk the leg INTO `route[index]` toward the goal the rail published, one
   * control frame at a time, and report whether the feet ever crossed the
   * vertex plane `vertexReached` requires at a turn.
   */
  function walkLeg(options: {
    route: readonly { x: number; y: number; z: number }[];
    index: number;
    goal: { x: number; y: number; z: number };
    stop: number;
    startBackUnits?: number;
    speedPerFrame?: number;
    maxFrames?: number;
  }): LegOutcome {
    const terrain = realTerrain();
    const speed = options.speedPerFrame ?? 0.08;
    const maxFrames = options.maxFrames ?? 2000;
    const vertex = options.route[options.index]!;
    const previous = options.route[options.index - 1]!;
    const incoming = new THREE.Vector3(
      vertex.x - previous.x, vertex.y - previous.y, vertex.z - previous.z
    ).normalize();
    const legLength = Math.hypot(
      vertex.x - previous.x, vertex.y - previous.y, vertex.z - previous.z
    );
    const back = Math.min(options.startBackUnits ?? 1.5, legLength);
    const startFoot = new THREE.Vector3(vertex.x, vertex.y, vertex.z)
      .addScaledVector(incoming, -back);
    const goal = new THREE.Vector3(options.goal.x, options.goal.y, options.goal.z);

    let centre = centreOver(startFoot);
    const start = centre.clone();
    let along = -back;
    let closest = Number.POSITIVE_INFINITY;
    let worstFootprintOffset = 0;
    const refusals = new Set<string>();
    let pushedFrames = 0;
    let frozenFrames = 0;
    let terminalWaypoint = new THREE.Vector3();

    for (let frame = 0; frame < maxFrames; frame += 1) {
      const up = liveUp(centre);
      // The FEET are what `vertexReached` measures, and they hang one standing
      // offset below the capsule centre along the tilted up.
      const feet = centre.clone().addScaledVector(up, -CENTRE_OFFSET);
      const toVertex = feet.clone().sub(new THREE.Vector3(vertex.x, vertex.y, vertex.z));
      const reached = toVertex.dot(incoming);
      along = Math.max(along, reached);
      closest = Math.min(closest, toVertex.length());
      if (surfaceGaitDistance(goal, centre, up) <= options.stop) break;

      const route = planLikeRuntime(terrain, centre, goal, up);
      if (route.mode === 'unreachable') { refusals.add('planner-unreachable'); break; }
      const waypoints = route.waypoints;
      const cursor = advanceCursor(waypoints, waypoints.length > 1 ? 1 : 0, centre, up);
      const snapped = waypoints[cursor] ?? goal;
      terminalWaypoint = waypoints[waypoints.length - 1]!.clone();

      const decision = terminalExactGoalHandoff({
        route,
        cursor,
        goal,
        action: route.mode === 'direct' ? 'direct' : 'walk',
        face: surfaceFaceFromUp(up),
        goalFace: dominantFaceForPosition(goal),
        up,
        crossFaceLegActive: false,
        certifyColumn: certifierFor(terrain, up)
      });
      if (decision.refusal && reached < 0) refusals.add(decision.refusal);
      // The same measurement `exactGoalFootprintColumns` bounds by the reach.
      const offset = goal.clone().sub(terminalWaypoint);
      offset.addScaledVector(up, -offset.dot(up));
      if (reached < 0) {
        worstFootprintOffset = Math.max(
          worstFootprintOffset,
          Math.max(Math.abs(offset.x), Math.abs(offset.z))
        );
      }

      const waypoint = applyTerminalExactGoal(
        snapped.clone(), goal, up, decision.handoff
      );
      const result = steer(centre, waypoint, up);
      if (!result.pushing) {
        frozenFrames += 1;
        // A body that stops pushing will never push again for this goal: route,
        // cursor and waypoint are all functions of a position that has stopped
        // changing. Stop rather than spin the loop.
        if (frozenFrames > 8) break;
        continue;
      }
      pushedFrames += 1;
      centre.addScaledVector(result.move, speed);
      // Gravity owns the normal axis: the feet stay on the surface the planner
      // cleared. The walk owns the tangent, and only the tangent.
      const settledUp = liveUp(centre);
      const foot = centre.clone().addScaledVector(settledUp, -CENTRE_OFFSET);
      foot.y = vertex.y;
      centre = foot.addScaledVector(settledUp, CENTRE_OFFSET);
    }

    return {
      along,
      closest,
      worstFootprintOffset,
      refusals: [...refusals],
      displacement: centre.distanceTo(start),
      pushedFrames,
      frozenFrames,
      terminalWaypoint
    };
  }

  /** Drive the REAL director to `holding-h` and read what it really publishes. */
  function publishedCommonGoals(): { index: number; target: readonly [number, number, number]; stop: number }[] {
    enterCommonGroundBeat('ch13-common');
    standAt(CG_POSES.E);
    const harness = createRailHarness(0.05);
    harness.run(600, () => commonGroundSnapshot().common.stage === 'holding-h');
    expect(commonGroundSnapshot().common.stage).toBe('holding-h');

    const published: { index: number; target: readonly [number, number, number]; stop: number }[] = [];
    for (let index = 1; index < CG_ROUTE_COMMON.length; index += 1) {
      standAt(CG_ROUTE_COMMON[index - 1]!);
      const plan = commonGroundRailPlan();
      expect(plan.reason, `cursor ${index}`).toBe('walking the common span');
      expect(plan.target, `cursor ${index}`).not.toBeNull();
      expect(goalVertexIndex(CG_ROUTE_COMMON, plan.target!), `cursor ${index}`).toBe(index);
      published.push({ index, target: plan.target!, stop: plan.arriveRadius });
    }
    return published;
  }

  beforeEach(() => {
    // No placed or persisted blocks: the terrain under the audit site is exactly
    // what the generator produces, which is what the hardware ran.
    voxelSystem.reset();
    unbind?.();
    unbind = registerCommonGroundWorld({
      worldId: '',
      footing: createFooting(PLANET_SIZE, STORY_SEED, STORY_PRIMARY_WORLD_ID),
      extraSolids: []
    });
  });

  afterEach(() => {
    voxelSystem.reset();
  });

  it('publishes a stop radius the steering can actually reach', () => {
    // THE OTHER HALF OF THE DEADLOCK. The walker releases every control inside
    // `NAVIGATION_STEER_DEAD_ZONE` of the point it is steering at, so a stop
    // radius LARGER than that dead zone can only ever be satisfied by luck —
    // and every unit of it is subtracted from the corner aim's budget.
    for (const { index, stop } of publishedCommonGoals()) {
      expect(stop, `cursor ${index} stop radius`).toBeLessThanOrEqual(
        NAVIGATION_STEER_DEAD_ZONE
      );
    }
  });

  it('aims through every corner, and never past the footprint the planner certifies', () => {
    for (const { index, target } of publishedCommonGoals()) {
      const vertex = CG_ROUTE_COMMON[index]!;
      const overshoot = Math.hypot(
        target[0] - vertex.x, target[1] - vertex.y, target[2] - vertex.z
      );
      if (overshoot > 0) {
        // FLOOR: past the vertex plane by more than the radius that releases the
        // controls, or the body parks short and the cursor can never advance.
        expect(overshoot, `cursor ${index} aim`).toBeGreaterThan(
          NAVIGATION_STEER_DEAD_ZONE
        );
      }
      // CEILING: the aim itself, before any tilt residue, still inside the
      // footprint one cell certification covers.
      expect(overshoot, `cursor ${index} aim`).toBeLessThanOrEqual(FOOTPRINT_REACH);
    }
  });

  it('walks the feet through every COMMON vertex plane, 6 and 9 included', () => {
    const published = publishedCommonGoals();
    expect(published.map(entry => entry.index)).toEqual([1, 2, 3, 4, 5, 6, 7, 8, 9]);
    const outcomes = published.map(({ index, target, stop }) => ({
      index,
      outcome: walkLeg({
        route: CG_ROUTE_COMMON,
        index,
        goal: { x: target[0], y: target[1], z: target[2] },
        stop
      })
    }));
    // Reported as ONE comparison so a regression names every vertex it broke,
    // not just the first. Vertices 3, 6 and 9 are the three the causal audit
    // predicted, and 6 and 9 were never reached on hardware at all.
    expect(outcomes.filter(entry => entry.outcome.refusals.length > 0).map(entry => ({
      vertex: entry.index,
      refusals: entry.outcome.refusals
    }))).toEqual([]);
    expect(outcomes.filter(entry => entry.outcome.worstFootprintOffset > FOOTPRINT_REACH)
      .map(entry => entry.index)).toEqual([]);
    for (const { index, outcome } of outcomes) {
      // The exact predicate `vertexReached` applies, on this walked body.
      //
      // AT A TURN it must have physically crossed the incoming plane — a cut
      // corner swings the body's own projection further than it walked, and
      // `routeProgressUnits` refuses that frame permanently. The terminal is
      // held to the same bar: the eighteenth unit is only walked by reaching C.
      // A straight vertex has no corner to cut, so standing inside the
      // (unchanged) vertex tolerance is enough there — and it still had to get
      // there by walking.
      if (turnsAt(CG_ROUTE_COMMON, index) || index === CG_ROUTE_COMMON.length - 1) {
        expect(outcome.along, `vertex ${index} crossing (${outcome.refusals.join()})`)
          .toBeGreaterThan(0);
      } else {
        expect(outcome.closest, `vertex ${index} reach (${outcome.refusals.join()})`)
          .toBeLessThanOrEqual(VERTEX_REACH);
      }
      expect(outcome.displacement, `vertex ${index} walked`).toBeGreaterThan(0.5);
      expect(outcome.pushedFrames, `vertex ${index} pushed`).toBeGreaterThan(3);
      // And it never had to be handed a column outside the terminal cell's own
      // certified footprint to get there.
      expect(outcome.worstFootprintOffset, `vertex ${index} footprint`)
        .toBeLessThanOrEqual(FOOTPRINT_REACH);
      expect(outcome.refusals, `vertex ${index} refusals`).toEqual([]);
    }
  });

  it('SURVEY corners are the negative control: they pass either way', () => {
    // The audit's discriminator. Every CG_ROUTE_LONG turn certified and arrived
    // even before this repair, including the negative-x overshoots — so a
    // COMMON-only failure is a real property of the western landform, not a
    // sign, quantization or parity asymmetry, and this repair is not a blanket
    // tightening. Both a positive-z and a negative-x corner are walked here.
    enterCommonGroundBeat('ch13-survey');
    for (const index of [1, 2, 13, 16]) {
      const vertex = CG_ROUTE_LONG[index]!;
      const previous = CG_ROUTE_LONG[index - 1]!;
      const incoming = new THREE.Vector3(
        vertex.x - previous.x, vertex.y - previous.y, vertex.z - previous.z
      ).normalize();
      const outcome = walkLeg({
        route: CG_ROUTE_LONG,
        index,
        // The same aim the survey traversal publishes at a turn.
        goal: {
          x: vertex.x + incoming.x * 0.24,
          y: vertex.y + incoming.y * 0.24,
          z: vertex.z + incoming.z * 0.24
        },
        stop: 0.15
      });
      expect(outcome.along, `survey vertex ${index}`).toBeGreaterThan(0);
      expect(outcome.refusals, `survey vertex ${index}`).toEqual([]);
    }
  });

  it('still REFUSES a goal whose footprint the planner does not own', () => {
    // The guard that produced the stall is the guard that must survive it. The
    // shipped 0.6 aim at COMMON vertex 3 put half the capsule over the water
    // column at (-46, ., 16); a deliberately unsafe aim there is still refused,
    // and the refusal still keeps the safe cell instead of the requested point.
    const terrain = realTerrain();
    const vertex = CG_ROUTE_COMMON[3]!;
    const centre = centreOver({ x: -42, y: 51.05, z: 16 });
    const up = liveUp(centre);
    const unsafe = new THREE.Vector3(vertex.x - 1.2, vertex.y, vertex.z);
    const route = planLikeRuntime(terrain, centre, unsafe, up);
    const decision = terminalExactGoalHandoff({
      route,
      cursor: route.waypoints.length - 1,
      goal: unsafe,
      action: 'walk',
      face: surfaceFaceFromUp(up),
      goalFace: dominantFaceForPosition(unsafe),
      up,
      crossFaceLegActive: false,
      certifyColumn: certifierFor(terrain, up)
    });
    expect(decision.handoff).toBe(false);
    expect(decision.refusal).not.toBeNull();
    const terminal = route.waypoints[route.waypoints.length - 1]!;
    const kept = applyTerminalExactGoal(terminal.clone(), unsafe, up, decision.handoff);
    expect(kept.distanceTo(terminal)).toBeCloseTo(0, 10);
    // ...and the water column itself is still unowned ground, not a rounding
    // complaint: the planner refuses to resolve a surface there at all.
    expect(certifierFor(terrain, up)(new THREE.Vector3(-46, vertex.y, 16))).toBeNull();
  });

  it('does not move a single authored vertex while doing it', () => {
    expect(CG_ROUTE_COMMON[0]).toEqual({ x: -42, y: 51.05, z: 12 });
    expect(CG_ROUTE_COMMON[3]).toEqual({ x: -44, y: 51.05, z: 16 });
    expect(CG_ROUTE_COMMON[6]).toEqual({ x: -48, y: 51.05, z: 18 });
    expect(CG_ROUTE_COMMON[9]).toEqual(CG_POSES.C);
    expect(CG_POSES.C).toEqual({ x: -48, y: 51.05, z: 12 });
    expect(CG_COMMON_ROUTE_UNITS).toBe(18);
    expect(NAVIGATION_STEER_DEAD_ZONE).toBe(0.2);
    expect(VOXEL_SCALE).toBe(2);
    expect(PLAYER_CAPSULE_RADIUS).toBe(0.5);
  });
});

