// --- CG-IMPL-014: the arrival is part of the trip -------------------------------------
//
// MEASURED on hardware (handoff-standby/flight-1): a fresh GB10 flight really
// lands at Origin and really earns the survey, but 109 telemetry samples across
// 28.5 seconds of the landed approach — from atMs 44980 to 73507, marker
// distance falling from 208 to 37 — publish `ch13:return:board`, "Kestrel hatch
// · board", while the autopilot's own route action is `walk`. The player is told
// to board the ship they have just landed and stepped out of, for the whole walk
// to W-7744.
//
// Signed scene-v3 binds the copy to the actual state of the trip under the SAME
// objective id and the SAME marker label. Every state below is produced by the
// real world and the real flight store — boarding, atmosphere, landing and
// disembarkation are the shipped transitions — and read back through the real
// `commonGroundGuidanceFacts` and the real objective resolver.

describe('the landed Origin approach is guided as an arrival, not a second departure', () => {
  const BASE_FLIGHT = ['Fly to Origin.', 'Follow the audit-site approach and land.'];
  const DISEMBARK = ['Disembark.', 'Follow the audit-site marker on foot.'];
  const ON_FOOT = ['Follow the audit-site marker on foot.'];

  function atWorld(worldId: string): void {
    resetSystemFlightForInterstellarArrival({
      system: STORY_COORDINATE,
      activePlanetId: worldId,
      locationMode: 'surface',
      pose: { position: [0, 0, 0], velocity: [0, 0, 0], quaternion: [0, 0, 0, 1] }
    });
  }

  /** The rung the REAL fact selector picks for the live world/flight state. */
  function rung() {
    const facts = commonGroundGuidanceFacts();
    const objective = resolveStoryObjectiveGuidance('ch13-return', facts)!;
    return { state: facts.ch13ReturnState, objective };
  }

  beforeEach(() => {
    resetTravel();
    enterCommonGroundBeat('ch13-return');
    markMilestone(STORY_MILESTONES.ch13ReturnChosen);
    standAt({ x: CG_POSES.W.x + 12, y: CG_POSES.W.y, z: CG_POSES.W.z });
  });

  afterEach(() => {
    resetTravel();
    resetSystemFlightStoreForTests();
  });

  it('keeps board and lift as the real readiness states away from Origin', () => {
    atWorld(TIDEGARDEN_WORLD_ID);
    // On foot, somewhere that is not Origin: the trip has not started, and the
    // shipped boarding rung is exactly right.
    expect(rung().state).toBe('board');
    expect(rung().objective.id).toBe('ch13:return:board');

    // Boarded and still down: lift. Control-only, and it keeps no world target.
    expect(enterShip()).toBe(true);
    expect(getSpaceFlightSnapshot()).toMatchObject({ phase: 'surface', controlMode: 'flight' });
    expect(rung().state).toBe('launch');
    expect(rung().objective.id).toBe('ch13:return:launch');

    // Underway: the signed flight work order, unchanged.
    enterAtmosphere();
    expect(getSpaceFlightSnapshot().phase).not.toBe('surface');
    expect(rung().state).toBe('origin');
    expect(rung().objective.workOrder).toEqual(BASE_FLIGHT);
  });

  it('retains the flight copy through the descent onto Origin itself', () => {
    atWorld(STORY_PRIMARY_WORLD_ID);
    expect(enterShip()).toBe(true);
    enterAtmosphere();
    // The enclosing world IS Origin and she is still flying it. Nothing about
    // being over the destination makes the next action anything but the landing.
    expect(getSpaceFlightSnapshot()).toMatchObject({ phase: 'descent', controlMode: 'flight' });
    expect(rung().state).toBe('origin');
    expect(rung().objective.workOrder).toEqual(BASE_FLIGHT);
  });

  it('asks for the disembark once the ship is actually down at Origin', () => {
    atWorld(STORY_PRIMARY_WORLD_ID);
    expect(enterShip()).toBe(true);
    enterAtmosphere();
    notifyLanded(); // the shipped grounding callback, not a fixture flag
    expect(getSpaceFlightSnapshot()).toMatchObject({ phase: 'surface', controlMode: 'flight' });

    const landed = rung();
    expect(landed.state).toBe('origin-disembark');
    expect(landed.objective.workOrder).toEqual(DISEMBARK);
    // It does NOT invent a task: no bracket token, no [F], no new key.
    expect(landed.objective.workOrder.join(' ')).not.toContain('[');
  });

  it('REGRESSION: stepping out on Origin does not republish the boarding order', () => {
    atWorld(STORY_PRIMARY_WORLD_ID);
    expect(enterShip()).toBe(true);
    enterAtmosphere();
    notifyLanded();
    // The shipped disembark control owns this transition; nothing here is new.
    expect(exitShip()).toBe(true);
    expect(getSpaceFlightSnapshot()).toMatchObject({ phase: 'surface', controlMode: 'fps' });

    const embodied = rung();
    // THE MEASURED DEFECT, IN ONE ASSERTION. This was 'board' for 28.5 seconds.
    expect(embodied.state).not.toBe('board');
    expect(embodied.state).toBe('origin-on-foot');
    expect(embodied.objective.id).toBe('ch13:return:origin');
    expect(embodied.objective.workOrder).toEqual(ON_FOOT);
    expect(embodied.objective.workOrder.join(' ')).not.toContain('Kestrel');
    expect(embodied.objective.workOrder.join(' ')).not.toContain('hatch');
  });

  it('is one objective with one label through all three phases', () => {
    const phases = (['origin', 'origin-disembark', 'origin-on-foot'] as const)
      .map(state => resolveStoryObjectiveGuidance('ch13-return', { ch13ReturnState: state })!);
    for (const phase of phases) {
      expect(phase.id).toBe('ch13:return:origin');
      expect(phase.markerLabel).toBe('Origin · audit site');
      expect(phase.kind).toBe('travel');
      expect(phase.requiresMarker).not.toBe(false);
    }
    // Each phase drops the step that has actually happened, and the surviving
    // line is literally the same sentence — not a paraphrase of it.
    expect(phases[0]!.workOrder).toEqual(BASE_FLIGHT);
    expect(phases[1]!.workOrder).toEqual(DISEMBARK);
    expect(phases[2]!.workOrder).toEqual([phases[1]!.workOrder[1]]);
    // ...and none of the three is the departure copy.
    const board = resolveStoryObjectiveGuidance('ch13-return', { ch13ReturnState: 'board' })!;
    for (const phase of phases) expect(phase.workOrder).not.toEqual(board.workOrder);
  });

  it('points the on-foot phase at the real W-7744 marker, never the hatch', () => {
    atWorld(STORY_PRIMARY_WORLD_ID);
    expect(enterShip()).toBe(true);
    enterAtmosphere();
    notifyLanded();
    expect(exitShip()).toBe(true);
    const marker = commonGroundMarkerTarget('ch13:return:origin');
    expect(marker).not.toBeNull();
    // The authored reference pose, resolved by the existing marker authority —
    // not a zero coordinate, not the ship, not a fabricated actor.
    expect(marker!.x).toBeCloseTo(CG_POSES.W.x, 6);
    expect(marker!.y).toBeCloseTo(CG_POSES.W.y, 6);
    expect(marker!.z).toBeCloseTo(CG_POSES.W.z, 6);
    const hatch = commonGroundMarkerTarget('ch13:return:board');
    if (hatch) expect(marker!.distanceTo(hatch)).toBeGreaterThan(0);
    // And it is a surface marker now that she is on the ground, not the
    // interplanetary projection the crossing uses.
    expect(commonGroundMarkerProjection('ch13:return:origin')).toBe('surface');
  });

  it('only the actual on-foot reach of W-7744 earns the arrival', () => {
    atWorld(STORY_PRIMARY_WORLD_ID);
    expect(enterShip()).toBe(true);
    enterAtmosphere();
    notifyLanded();

    // Landed, still boarded, standing on the marker: nothing is earned. Landing
    // and world activation are not the arrival.
    standAt(CG_POSES.W);
    tickCommonGround(0.05);
    expect(hasMilestone(STORY_MILESTONES.ch13OriginLanded)).toBe(false);
    expect(rung().state).toBe('origin-disembark');

    // On foot but short of it: still nothing.
    expect(exitShip()).toBe(true);
    standAt({ x: CG_POSES.W.x + 9, y: CG_POSES.W.y, z: CG_POSES.W.z });
    tickCommonGround(0.05);
    expect(hasMilestone(STORY_MILESTONES.ch13OriginLanded)).toBe(false);
    expect(rung().state).toBe('origin-on-foot');

    // Physically there, on her own feet. Now, and only now.
    standAt(CG_POSES.W);
    tickCommonGround(0.05);
    expect(hasMilestone(STORY_MILESTONES.ch13OriginLanded)).toBe(true);
  });

  it('replaces the standing copy silently, with no second entry acknowledgement', () => {
    // The exact sequence `syncEmergentObjectiveGuidance` runs: publish, and when
    // the id is unchanged but the work order has become untrue, clear as a
    // 'replace' and republish. The objective director only cues an id it has not
    // entered before, so the copy moves and the acknowledgement does not.
    resetGuidedObjectiveFeedbackForTests();
    clearGuidedStoryObjective('reset');
    const cues: string[] = [];
    const stop = subscribeStoryUxFeedback(cue => {
      cues.push(`${cue.type}:${'objectiveId' in cue ? cue.objectiveId : ''}`);
    });
    try {
      const phases = (['origin', 'origin-disembark', 'origin-on-foot'] as const)
        .map(state => resolveStoryObjectiveGuidance('ch13-return', { ch13ReturnState: state })!);
      for (const phase of phases) {
        if (!activateGuidedStoryObjective(phase, phase.markerLabel)) {
          const active = getActiveGuidedStoryObjective();
          expect(active!.id).toBe(phase.id);
          if (active!.workOrder.join('�') !== phase.workOrder.join('�')) {
            clearGuidedStoryObjective('replace');
            activateGuidedStoryObjective(phase, phase.markerLabel);
          }
        }
        // The standing order the HUD actually shows really did change.
        expect(getActiveGuidedStoryObjective()!.workOrder).toEqual(phase.workOrder);
      }
      // One acknowledgement for the whole arrival, on its entry.
      expect(cues.filter(cue => cue === 'objective-enter:ch13:return:origin')).toHaveLength(1);
      expect(cues.filter(cue => cue.startsWith('objective-enter'))).toHaveLength(1);
      // And no completion receipt was published by a copy change.
      expect(cues.filter(cue => cue.startsWith('objective-complete'))).toHaveLength(0);
    } finally {
      stop();
      clearGuidedStoryObjective('reset');
      resetGuidedObjectiveFeedbackForTests();
    }
  });
});
